        #10;

        // Run through multiple clock cycles to test counting and enable sticky/pulse behavior
        // Let's run enough cycles to catch rollover from 9 to 0, 99 to 100, 999 to 1000, 9999 to 0000.

        // Cycle 1: q should be 0001
        @(posedge clk);
        #1;
        if (q !== 16'h0001) begin
            $display("ERROR: At q=1, got 0x%h", q);
            errors = errors + 1;
        end

        // Fast forward to ones = 9 (q = 9)
        // Currently q=1, we need 8 more cycles to reach 9.
        repeat (8) @(posedge clk);
        #1;
        if (q !== 16'h0009) begin
            $display("ERROR: Expected q=0x0009, got 0x%h", q);
            errors = errors + 1;
        end

        // Next cycle (10th), ones rolls over from 9 to 0, tens increments from 0 to 1 (q = 0010)
        // The RTL uses blocking/non-blocking logic or conditional updates for `ena`.
        // Let's check `ena` and `q` behavior right after this clock edge.
        @(posedge clk);
        #1;
        if (q !== 16'h0010) begin
            $display("ERROR: Rollover check failed, expected q=0x0010, got 0x%h", q);
            errors = errors + 1;
        end
        // In the RTL: when ones == 4'b1001, ena[0] <= 1. Otherwise ena[0] <= 0.
        // Wait! Let's check if `ena` is supposed to be a single-cycle pulse or level-based.
        // The spec says: "output an enable signal indicating when each of the upper three digits should be incremented."
        // Usually, an enable is a 1-cycle strobe. Let's verify what the candidate RTL actually does with `ena`.

        // Let's push up to 99 (q = 0099)
        // From 0010 to 0099 is 89 cycles. Let's just run a loop to test a bunch of values.

        // Let's test a sequence and check specific rollover points.
        // We can run a short bounded loop up to 105 to check 99->100 rollover.
        for (i = 0; i < 90; i = i + 1) begin
            @(posedge clk);
        end
        #1;
        // Now we should be at q = 0099 (since we started from q=0, did 8+1+89 = 98 increments? Wait, let's trace carefully.)
        // Let's reset and do a controlled test from 0 to 1000.
        reset = 1;
        @(posedge clk);
        #1;
        reset = 0;

        // Run 99 cycles -> q should be 0099
        repeat (99) @(posedge clk);
        #1;
        if (q !== 16'h0099) begin
            $display("ERROR: Expected 0x0099, got 0x%h", q);
            errors = errors + 1;
        end

        // Next cycle (100th) -> q should become 0100
        @(posedge clk);
        #1;
        if (q !== 16'h0100) begin
            $display("ERROR: Rollover 99->100 failed, got 0x%h", q);
            errors = errors + 1;
        end

        // Check 999 -> 1000 rollover
        reset = 1;
        @(posedge clk);
        #1;
        reset = 0;

        repeat (999) @(posedge clk);
        #1;
        if (q !== 16'h0999) begin
            $display("ERROR: Expected 0x0999, got 0x%h", q);
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        if (q !== 16'h1000) begin
            $display("ERROR: Rollover 999->1000 failed, got 0x%h", q);
            errors = errors + 1;
        end

        // Check 9999 -> 0000 rollover
        reset = 1;
        @(posedge clk);
        #1;
        reset = 0;

        repeat (9999) @(posedge clk);
        #1;
        if (q !== 16'h0000) begin
            $display("ERROR: Rollover 9999->0000 failed, got 0x%h", q);
            errors = errors + 1;
        end

        // Final result reporting
        #10;
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
